//! Markdown is generated by the authorized host; only the chosen destination is local.
use super::{Event as ParentEvent, message, reader};
use crate::app::{App, Message, components::system_settings_common::*};
use iced::{Element, Task, widget::{button, row, text}};
use std::path::PathBuf;
use vw_gateway_client::{AgentAppsReadError, vw_api_types::external_session::*};

#[derive(Clone, Copy, Debug)]
pub enum Destination { Clipboard, File }
#[derive(Clone, Debug)]
pub enum Event {
    Start(Destination, bool),
    Loaded(reader::Scope, Destination, Result<SessionMarkdownResponse, AgentAppsReadError>),
    Selected(reader::Scope, String, Option<PathBuf>),
    Saved(reader::Scope, bool),
}
fn msg(event: Event) -> Message { message(ParentEvent::Export(event)) }

pub(super) fn update(app: &mut App, event: Event) -> Task<Message> {
    let Some(scope) = reader::current_scope(app) else { return Task::none(); };
    let state = &mut app.apps_catalog.external_sessions;
    let Some(reader) = &mut state.reader else { return Task::none(); };
    match event {
        Event::Start(destination, single) => {
            if reader.exporting { return Task::none(); }
            if !state.page.as_ref().is_some_and(|page| page.sessions.iter().any(|session|
                session.identity == reader.identity && session.capabilities.export_markdown)) {
                return app.show_error_toast("当前会话不支持 Markdown 导出");
            }
            let turn_key = if single {
                let Some(turn) = reader.turns.get(reader.active) else { return Task::none(); };
                Some(turn.turn_id.clone())
            } else { None };
            let Ok(client) = crate::app::config::gateway_client() else { return Task::none(); };
            let request = SessionMarkdownRequest { identity: reader.identity.clone(), turn_key,
                include_thinking: false };
            let token = app.apps_catalog.token.clone();
            reader.exporting = true;
            Task::perform(async move {
                msg(Event::Loaded(scope, destination, client.external_session_markdown(&request, &token).await))
            }, |message| message)
        }
        Event::Loaded(other, destination, result) => {
            if other != scope || !reader.exporting { return Task::none(); }
            let response = match result {
                Ok(response) => response,
                Err(_) => {
                    reader.exporting = false;
                    return app.show_error_toast("Markdown 获取失败，请检查主机授权并重试");
                }
            };
            match destination {
                Destination::Clipboard => {
                    reader.exporting = false;
                    Task::batch([iced::clipboard::write(response.markdown), app.show_success_toast("已复制 Markdown")])
                }
                Destination::File => Task::perform(async move {
                    let selected = rfd::AsyncFileDialog::new().add_filter("Markdown", &["md"])
                        .set_file_name("session.md").save_file().await;
                    msg(Event::Selected(scope, response.markdown, selected.map(|file| file.path().to_owned())))
                }, |message| message),
            }
        }
        Event::Selected(other, markdown, path) => {
            if other != scope || !reader.exporting { return Task::none(); }
            let Some(path) = path else { reader.exporting = false; return Task::none(); };
            // Revalidate the reader after the native picker, before any write.
            Task::perform(async move {
                msg(Event::Saved(scope, tokio::fs::write(path, markdown).await.is_ok()))
            }, |message| message)
        }
        Event::Saved(other, success) => {
            if other != scope || !reader.exporting { return Task::none(); }
            reader.exporting = false;
            if success { app.show_success_toast("Markdown 已保存") }
            else { app.show_error_toast("Markdown 保存失败，请检查目标目录权限与磁盘空间后重试") }
        }
    }
}

pub(super) fn controls<'a>(state: &super::State, reader: &reader::State) -> Element<'a, Message> {
    let enabled = !reader.exporting && state.page.as_ref().is_some_and(|page|
        page.sessions.iter().any(|s| s.identity == reader.identity && s.capabilities.export_markdown));
    let mut controls = row![].spacing(8).wrap();
    for (label, destination, single) in [
        ("复制本轮 Markdown", Destination::Clipboard, true),
        ("复制整段 Markdown", Destination::Clipboard, false),
        ("导出本轮 Markdown", Destination::File, true),
        ("导出整段 Markdown", Destination::File, false),
    ] {
        controls = controls.push(button(text(label)).padding([8, 12]).style(rounded_action_btn_style)
            .on_press_maybe((enabled && (!single || reader.turns.get(reader.active).is_some()))
                .then(|| msg(Event::Start(destination, single)))));
    }
    controls.into()
}
